"""Capture packaged inputs and fixture sources before building immutable benchmark images."""
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def capture():
    sources = []
    for path in ROOT.rglob('*'):
        relative = path.relative_to(ROOT)
        if any(part in ['target', 'node_modules', 'results', '.idea', '__pycache__'] for part in relative.parts):
            continue
        if path.is_file() and (path.suffix in ['.java', '.py', '.xml', '.properties', '.ps1'] or path.name == 'Dockerfile'):
            data = path.read_bytes()
            sources.append({'path': relative.as_posix(), 'sha256': hashlib.sha256(data).hexdigest(),
                            'content': data.decode('utf-8')})
    jars = []
    for directory in [ROOT/'guicedee/target', ROOT/'quarkus/target/quarkus-app']:
        for path in directory.rglob('*.jar'):
            jars.append({'path': path.relative_to(ROOT).as_posix(),
                         'sha256': hashlib.sha256(path.read_bytes()).hexdigest()})
    return {'sourcesAtImageBuild': sources, 'packagedJars': jars,
            'note': 'Source snapshot at image packaging; build the Maven reactor before packaging images.'}


if __name__ == '__main__':
    (ROOT/'docker/build-provenance.json').write_text(json.dumps(capture(), indent=2)+'\n', encoding='utf-8')

"""Deterministic OAuth/commercetools fixture. It validates and records real SDK traffic."""
import collections
import json
import socket
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer


class Upstream(ThreadingHTTPServer):
    daemon_threads = True

    def __init__(self, host="127.0.0.1"):
        super().__init__((host, 0), Handler)
        self.events = []
        self.counts = collections.Counter()
        self.lock = threading.Lock()

    def record(self, method, path, status):
        with self.lock:
            self.events.append({"method": method, "path": path, "status": status})


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def setup(self):
        super().setup()
        self.connection.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)

    def log_message(self, *_): pass

    def handle(self):
        try: super().handle()
        except (ConnectionResetError, BrokenPipeError): pass

    def reply(self, status, body):
        self.server.record(self.command, self.path, status)
        data = json.dumps(body).encode() if not isinstance(body, str) else body.encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        try: self.wfile.write(data)
        except (BrokenPipeError, ConnectionResetError): pass

    def do_POST(self):
        raw = self.rfile.read(int(self.headers.get("Content-Length", 0)))
        if self.path == "/oauth/token":
            valid = self.headers.get("Authorization") == "Basic Zml4dHVyZTpmaXh0dXJl" and b"grant_type=client_credentials" in raw
            return self.reply(200 if valid else 401, {"access_token": "fixture-token", "token_type": "Bearer", "expires_in": 3600})
        if self.path == "/benchmark/graphql":
            try: valid = "inventoryEntries" in json.loads(raw)["query"]
            except (ValueError, KeyError): valid = False
            valid &= self.headers.get("Authorization") == "Bearer fixture-token"
            return self.reply(200 if valid else 400, {"data": {"inventoryEntries": {"results": [{"availableQuantity": 40}]}}})
        self.reply(404, {"error": "unknown fixture path"})

    def do_GET(self):
        if self.path == "/benchmark":
            if self.headers.get("Authorization") != "Bearer fixture-token": return self.reply(401, {})
            return self.reply(200, {"key": "benchmark", "name": "Fixture shop", "version": 1,
                                   "createdAt": "2026-01-01T00:00:00Z", "currencies": ["ZAR"], "countries": ["ZA"], "languages": ["en"]})
        if self.path.startswith("/flaky/"):
            with self.server.lock:
                self.server.counts[self.path] += 1
                count = self.server.counts[self.path]
            return self.reply(503 if count < 3 or self.path.endswith("always") else 200, "ok")
        if self.path == "/slow":
            threading.Event().wait(0.25)
            return self.reply(200, "late")
        self.reply(404, {})

package bench.quarkus;
import jakarta.inject.Inject;
import jakarta.enterprise.context.ApplicationScoped;
import bench.workload.Workload;
import jakarta.ws.rs.*;
import jakarta.ws.rs.core.*;
import io.smallrye.mutiny.Uni;
import java.util.Map;
@Path("/") @Produces(MediaType.APPLICATION_JSON) @ApplicationScoped
public class Resource {
    @Inject Service service;
    @GET @Path("ready") public Map<String,Object> ready() { return Map.of("ready",true); }
    @POST @Path("quote") @Consumes(MediaType.APPLICATION_JSON)
    @org.eclipse.microprofile.openapi.annotations.Operation(summary="Vendor SDK REST and GraphQL shipping quote")
    public Uni<Response> quote(Workload.Order order, @QueryParam("persist") boolean persist) {
        if(order==null || order.sku()==null || order.sku().isBlank() || order.quantity()<1)
            return Uni.createFrom().item(error(400,"INVALID_ORDER"));
        return service.quote(order).flatMap(body -> persist
            ? service.firebase(order.sku()).map(saved -> Response.ok(body).build())
            : Uni.createFrom().item(Response.ok(body).build()))
            .onFailure().invoke(Throwable::printStackTrace).onFailure().recoverWithItem(f->error(502,"UPSTREAM_FAILURE"));
    }
    @GET @Path("retry/{id}") public Uni<Response> retry(@PathParam("id") String id) {
        return service.retry(id).map(v->Response.ok(Map.of("result",v)).build())
            .onFailure().recoverWithItem(f->error(502,"UPSTREAM_FAILURE"));
    }
    @GET @Path("timeout") public Uni<Response> timeout() {
        return service.timeout().map(v->Response.ok(Map.of("result",v)).build())
            .onFailure().recoverWithItem(f->error(504,"UPSTREAM_TIMEOUT"));
    }
    @GET @Path("firebase/{id}") public Uni<Response> firebase(@PathParam("id") String id) {
        return service.firebase(id).map(body->Response.ok(body).build())
            .onFailure().recoverWithItem(f->error(502,"FIREBASE_FAILURE"));
    }
    private Response error(int status,String code) { return Response.status(status).entity(Map.of("error",Map.of("code",code,"status",status))).build(); }
}

package bench.quarkus;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.inject.Inject;
import bench.workload.Workload;
import io.smallrye.mutiny.Uni;
import org.eclipse.microprofile.faulttolerance.*;
import java.util.Map;
@ApplicationScoped
public class Service {
    private final Workload workload = new Workload(org.eclipse.microprofile.config.ConfigProvider.getConfig().getValue("BENCH_UPSTREAM", String.class));
    @Inject io.micrometer.core.instrument.MeterRegistry metrics;
    
    public Uni<Map<String,Object>> quote(Workload.Order order) {
        metrics.counter("benchmark_quotes").increment();
        return Uni.createFrom().completionStage(() -> workload.quote(order));
    }
    @Retry(maxRetries=2, delay=20, jitter=0)
    public Uni<String> retry(String id) { return Uni.createFrom().completionStage(() -> workload.remote("/flaky/"+id)); }
    @Timeout(50)
    public Uni<String> timeout() { return Uni.createFrom().completionStage(() -> workload.remote("/slow")); }
    public Uni<Map<String,Object>> firebase(String id) { return Uni.createFrom().completionStage(() -> workload.firebase(id)); }
}

